<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';
import {request,kinds,relationKinds} from './api';
import ChartView from './ChartView.vue';
const newId=()=>crypto.randomUUID();
const tabs=['总览','资产拓扑','告警事件','日志诊断','图表','模型和数据源','审计'];const tab=ref('总览');const space=ref('real');const busy=ref(false);const error=ref('');const notice=ref('');
const assets=ref<any[]>([]),relations=ref<any[]>([]),incidents=ref<any[]>([]),logs=ref<any[]>([]),charts=ref<any[]>([]),audit=ref<any[]>([]);const settings=ref<any>({prometheusUrl:'',modelUrl:'',modelName:'',externalModel:false,allowedExternalFields:[]});const diagnosis=ref<any>();const prometheus=ref<any>();const query=ref('');const paste=ref('');const useModel=ref(false);const logSystem=ref('手工输入');const logLevel=ref('error');const importText=ref('');
const blankAsset=()=>({id:'',name:'',kind:'application',locked:true});const asset=ref(blankAsset());const blankRelation=()=>({id:'',from:'',to:'',kind:'deployed_on',locked:true});const relation=ref(blankRelation());const prompt=ref('按严重级别统计告警');const schema=ref<any>({id:'',title:'告警分布',dataset:'incidents',groupBy:'severity',type:'bar',hours:24,limit:20});const chartData=ref<any[]>([]);
const api=(path:string,body?:unknown,method?:string)=>request(space.value,path,body,method);
async function act(work:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await work()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function load(){const requestedSpace=space.value;const data=await Promise.all(['assets','relations','incidents','logs','charts','audit','settings'].map(p=>request(requestedSpace,p)));if(requestedSpace!==space.value)return;[assets.value,relations.value,incidents.value,logs.value,charts.value,audit.value,settings.value]=data;}
async function saveAsset(){await act(async()=>{const id=asset.value.id||crypto.randomUUID();await api('assets/'+id,{...asset.value,id},'PUT');asset.value=blankAsset();await load();notice.value='资产已保存'})}
async function saveRelation(){await act(async()=>{const id=relation.value.id||crypto.randomUUID();await api('relations/'+id,{...relation.value,id},'PUT');relation.value=blankRelation();await load();notice.value='关系已保存'})}
async function remove(kind:string,id:string){await act(async()=>{await api(`${kind}/${id}`,undefined,'DELETE');await load()})}
async function analyze(){await act(async()=>{diagnosis.value=await api('analyze',{text:paste.value,useModel:useModel.value})})}
async function search(){await act(async()=>{logs.value=await api('logs?q='+encodeURIComponent(query.value)+'&hours=24&limit=100')})}
async function preview(){await act(async()=>{chartData.value=await api('charts/query',schema.value)})}
const groupFields=computed(()=>schema.value.dataset==='assets'?['kind','source']:schema.value.dataset==='logs'?['level','system']:['severity','status']);
const label=(id:string)=>assets.value.find(a=>a.id===id)?.name??id;
const nodePos=(id:string)=>{const i=Math.max(0,assets.value.findIndex(a=>a.id===id));return {x:120+(i%4)*210,y:65+Math.floor(i/4)*120}};
const active=computed(()=>incidents.value.filter(x=>x.status==='firing').length);
watch(space,()=>{diagnosis.value=undefined;prometheus.value=undefined;chartData.value=[];asset.value=blankAsset();relation.value=blankRelation();act(load)});
onMounted(()=>act(load));
</script>
<template>
<div class="layout"><aside><div class="brand"><span class="brand-icon">◈</span> 观云 <small>AIOPS</small></div><div class="nav-caption">运维工作空间</div><nav><button v-for="(item,i) in tabs" :key="item" :class="{active:tab===item}" @click="tab=item"><span>{{ ['◫','⌘','◉','≡','▥','⚙','◷'][i] }}</span>{{item}}</button></nav><div class="side-footer"><span class="dot"></span> 本地单用户 MVP<br><small>仅回环监听 · 无生产修复权限</small></div></aside>
<main><header><div><div class="eyebrow">INFRASTRUCTURE INTELLIGENCE</div><h1>{{tab}}</h1></div><div class="toolbar"><label>数据空间 <select v-model="space" :disabled="busy" aria-label="数据空间"><option value="real">真实数据</option><option value="demo">DEMO 演示</option></select></label><button :disabled="busy" @click="act(load)">刷新</button><button v-if="space==='demo'" @click="act(async()=>{await api('seed',{});await load()})">载入演示数据</button></div></header>
<div v-if="space==='demo'" class="banner demo">DEMO 演示空间 · 数据为示例，与真实资产、告警和日志隔离</div><div v-else class="banner">真实数据空间 · 未接入的数据保持空状态；所有诊断均需人工验证</div>
<div v-if="error" role="alert" class="banner error">{{error}}</div><div v-if="notice" role="status" class="banner success">{{notice}}</div><div v-if="busy" role="status" class="loading">正在处理…</div>
<section v-if="tab==='总览'"><div class="stats"><article><span>受管资产</span><strong>{{assets.length}}</strong><small>物理机 / 虚拟机 / Kubernetes</small></article><article><span>活跃告警</span><strong>{{active}}</strong><small>按完整标签聚合事件</small></article><article><span>资产关系</span><strong>{{relations.length}}</strong><small>部署、归属与调用分开记录</small></article><article><span>保存图表</span><strong>{{charts.length}}</strong><small>受控查询 · 无任意 SQL</small></article></div><div class="columns"><article class="panel"><h2>告警动态 <small>最近事件</small></h2><div v-if="!incidents.length" class="empty">尚无告警事件<br>配置 Alertmanager webhook 后接收真实告警</div><div v-for="i in incidents.slice(0,6)" :key="i.id" class="row"><span class="pill">{{i.severity}}</span><div><b>{{i.name}}</b><small>{{i.target}}</small></div><span>{{i.status}}</span></div><button @click="tab='告警事件'">查看全部事件 →</button></article><article class="panel"><h2>数据接入</h2><p>Prometheus：{{settings.prometheusUrl?'已配置（尚需查询验证）':'未配置'}}</p><p>AI 模型：{{settings.modelUrl?'已配置（尚需调用验证）':'未配置 · 规则分析可用'}}</p><p>Trace / CPU Profiling：未接入</p><button @click="tab='模型和数据源'">管理连接 →</button><div class="hint">免 Agent 优先复用现有监控、日志与 API。拓扑部署边不代表真实调用链。</div></article></div></section>
<section v-if="tab==='资产拓扑'"><article class="panel"><h2>资产关系图 <small>部署 / 归属 / 人工调用</small></h2><div v-if="!assets.length" class="empty">尚无资产。手工录入，或导入 Kubernetes Pod List。</div><svg v-else class="topology" :viewBox="`0 0 900 ${Math.max(220,Math.ceil(assets.length/4)*120)}`" role="img" aria-label="资产拓扑"><g v-for="r in relations" :key="r.id"><line :x1="nodePos(r.from).x" :y1="nodePos(r.from).y" :x2="nodePos(r.to).x" :y2="nodePos(r.to).y" :stroke="r.kind==='calls'?'#df9a43':'#87a8b4'" :stroke-dasharray="r.kind==='calls'?'6 4':'0'"/><text :x="(nodePos(r.from).x+nodePos(r.to).x)/2" :y="(nodePos(r.from).y+nodePos(r.to).y)/2-18">{{relationKinds[r.kind]}}</text></g><g v-for="a in assets" :key="a.id" :transform="`translate(${nodePos(a.id).x},${nodePos(a.id).y})`"><rect x="-85" y="-23" width="170" height="46" rx="9"/><text text-anchor="middle" y="5">{{a.name.slice(0,16)}}</text></g></svg><div class="hint">没有观测调用边或火焰图数据。请对接 OpenTelemetry tracing / 持续 profiling；不从日志推造调用链或 CPU 栈。</div></article>
<div class="columns"><article class="panel"><h2>{{asset.id?'编辑资产':'新增资产'}}</h2><form @submit.prevent="saveAsset"><label>资产名称<input v-model="asset.name" required maxlength="120" aria-label="资产名称"></label><label>资产类型<select v-model="asset.kind"><option v-for="(v,k) in kinds" :value="k">{{v}}</option></select></label><label class="check"><input type="checkbox" v-model="asset.locked">人工锁定（人工来源始终优先）</label><button class="primary" :disabled="busy">保存资产</button><button type="button" @click="asset=blankAsset()">清空</button></form></article><article class="panel"><h2>{{relation.id?'编辑关系':'新增关系'}}</h2><form @submit.prevent="saveRelation"><label>起点<select v-model="relation.from" required aria-label="关系起点"><option value="">选择资产</option><option v-for="a in assets" :value="a.id">{{a.name}}</option></select></label><label>终点<select v-model="relation.to" required aria-label="关系终点"><option value="">选择资产</option><option v-for="a in assets" :value="a.id">{{a.name}}</option></select></label><label>关系类型<select v-model="relation.kind"><option v-for="(v,k) in relationKinds" :value="k">{{v}}</option></select></label><label class="check"><input type="checkbox" v-model="relation.locked">人工锁定</label><button class="primary" :disabled="busy">保存关系</button><button type="button" @click="relation=blankRelation()">清空</button></form></article></div>
<article class="panel"><h2>资产清单</h2><table><thead><tr><th>名称</th><th>类型</th><th>来源 / 锁定</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="a in assets" :key="a.id"><td>{{a.name}}</td><td>{{kinds[a.kind]}}</td><td>{{a.source}} / {{a.locked?'锁定':'未锁定'}}</td><td>{{new Date(a.updatedAt).toLocaleString()}}</td><td><button @click="asset={...a}">编辑</button><button @click="remove('assets',a.id)">删除</button></td></tr></tbody></table><h2>关系清单</h2><div v-for="r in relations" :key="r.id" class="row"><span>{{label(r.from)}} → {{label(r.to)}} · {{relationKinds[r.kind]}} · {{r.source}} · {{r.locked?'锁定':'未锁定'}}</span><button @click="relation={...r}">编辑</button><button @click="remove('relations',r.id)">删除</button></div></article><article class="panel"><h2>Kubernetes 导入</h2><p>在授权的集群环境执行 kubectl get pods -A -o json，将 Pod List 粘贴到此处。仅导入部署关系，保留人工覆盖。</p><textarea v-model="importText" placeholder="Kubernetes Pod List JSON" maxlength="240000"></textarea><button @click="act(async()=>{await api('imports/kubernetes',JSON.parse(importText));await load();notice='导入完成，人工覆盖已保留'})">导入部署拓扑</button></article></section>
<section v-if="tab==='告警事件'"><article class="panel"><h2>告警事件 <small>Worker 自动规则诊断 · 2 秒周期</small></h2><p>接入路径：POST /api/webhooks/alertmanager，服务端配置 AIOPS_WEBHOOK_TOKEN。重复标签集合聚合计数，恢复事件更新状态。</p><label class="check"><input type="checkbox" v-model="useModel">手工诊断时请求配置的 AI 模型（失败明确回退）</label><div v-if="!incidents.length" class="empty">未收到告警。演示请切换 DEMO 空间。</div><div v-for="i in incidents" :key="i.id" class="row"><span class="pill">{{i.severity}}</span><div><b>{{i.name}}</b><small>{{i.target}} · {{i.status}} · 收到 {{i.count}} 次</small><small>{{i.diagnosis?.mode??'等待 Worker 诊断'}}</small></div><button @click="diagnosis=i.diagnosis">查看分析</button><button @click="act(async()=>{diagnosis=await api(`incidents/${i.id}/diagnose`,{text:'',useModel});await load()})">重新诊断</button></div></article></section>
<section v-if="tab==='日志诊断'"><div class="columns"><article class="panel"><h2>粘贴报错 · 诊断</h2><textarea v-model="paste" maxlength="10000" aria-label="报错内容" placeholder="粘贴错误日志（最多 10,000 字符），避免包含敏感信息"></textarea><label class="check"><input type="checkbox" v-model="useModel">使用已配置模型；默认仅本地规则</label><button class="primary" :disabled="!paste||busy" @click="analyze">分析报错</button><h3>保存至日志工作集</h3><input v-model="logSystem" aria-label="日志系统" placeholder="系统名称"><select v-model="logLevel"><option>error</option><option>warning</option><option>info</option></select><button :disabled="!paste||busy" @click="act(async()=>{await api('logs',{id:'',system:logSystem,level:logLevel,message:paste,updatedAt:new Date().toISOString()});await search();notice='已脱敏保存'})">脱敏保存日志</button><p class="hint">此工作集用于有限样本排查，不替代日志数据库。内网模型收到脱敏文本；外网模型只收到明确许可的规则分类。</p></article><article class="panel"><h2>日志检索 <small>最近 24 小时 · 最多 100 条</small></h2><form @submit.prevent="search" class="toolbar"><input v-model="query" maxlength="200" aria-label="日志关键词" placeholder="关键词"><button>检索</button></form><div v-if="!logs.length" class="empty">没有匹配日志</div><div v-for="l in logs" :key="l.id" class="log"><small>{{l.system}} · {{l.level}} · {{new Date(l.updatedAt).toLocaleString()}}</small><pre>{{l.message}}</pre><button @click="paste=l.message">填入分析</button></div></article></div></section>
<article v-if="diagnosis&&['告警事件','日志诊断'].includes(tab)" class="panel diagnosis"><h2>诊断报告 <small>{{diagnosis.mode}}</small></h2><div class="columns"><div v-for="(label,key) in {facts:'事实',evidence:'证据（不可信输入）',candidates:'候选根因',gaps:'证据缺口',verification:'验证步骤',actions:'处理建议'}"><h3>{{label}}</h3><ul><li v-for="text in diagnosis[key]">{{text}}</li></ul></div></div><div v-if="diagnosis.modelAdvice"><h3>模型建议 · 未验证</h3><pre>{{diagnosis.modelAdvice}}</pre></div></article>
<section v-if="tab==='图表'"><div class="columns"><article class="panel"><h2>自然语言 → 受控图表</h2><input v-model="prompt" maxlength="500" aria-label="图表需求"><button @click="act(async()=>{const result=await api('charts/interpret',{text:prompt});schema=result.schema;notice=result.mode})">生成配置</button><p class="hint">当前为规则解析。只支持资产、告警、日志计数；生成配置经服务端白名单校验，不执行 SQL/JS。</p><label>标题<input v-model="schema.title" maxlength="120"></label><label>数据集<select v-model="schema.dataset" @change="schema.groupBy=groupFields[0]"><option value="assets">资产</option><option value="incidents">告警</option><option value="logs">日志</option></select></label><label>分组<select v-model="schema.groupBy"><option v-for="f in groupFields">{{f}}</option></select></label><label>图形<select v-model="schema.type"><option value="bar">柱状图</option><option value="pie">饼图</option></select></label><label>小时范围<input type="number" min="1" max="168" v-model.number="schema.hours"></label><label>最大分组数<input type="number" min="1" max="50" v-model.number="schema.limit"></label><button @click="preview">预览</button><button class="primary" @click="act(async()=>{const id=schema.id||newId();await api('charts/'+id,{...schema,id},'PUT');await load();notice='图表已保存'})">保存图表</button></article><article class="panel"><h2>{{schema.title}}</h2><ChartView :data="chartData" :type="schema.type"/><h3>已保存图表</h3><div v-for="c in charts" class="row"><button @click="schema={...c};preview()">{{c.title}}</button><button @click="remove('charts',c.id)">删除</button></div></article></div></section>
<section v-if="tab==='模型和数据源'"><article class="panel"><h2>连接配置</h2><p class="hint">密钥仅通过服务端环境变量配置。此页面不接收或返回密钥。URL 必须为服务端显式批准的 IPv4 origin，禁止重定向和元数据端点。</p><form @submit.prevent="act(async()=>{settings=await api('settings',settings,'PUT');notice='配置已保存，尚需验证可用性'})"><label>Prometheus 基址<input v-model="settings.prometheusUrl" placeholder="未配置，如 http://10.0.0.10:9090"></label><label>OpenAI 兼容模型基址<input v-model="settings.modelUrl" placeholder="未配置，如 http://10.0.0.20:8000/v1"></label><label>模型名称<input v-model="settings.modelName" maxlength="100"></label><label class="check"><input type="checkbox" v-model="settings.externalModel">这是外网模型</label><label v-if="settings.externalModel" class="check"><input type="checkbox" :checked="settings.allowedExternalFields?.includes('ruleCategory')" @change="settings.allowedExternalFields=($event.target as HTMLInputElement).checked?['ruleCategory']:[]">明确允许外发 ruleCategory（固定分类；不包含原文、实例或证据）</label><button class="primary">保存连接配置</button></form><button v-if="space==='real'" @click="act(async()=>{prometheus=await api('prometheus?metric=up')})">只读查询 Prometheus up</button><pre v-if="prometheus">{{JSON.stringify(prometheus,null,2)}}</pre><p>Webhook / 模型密钥：通过 AIOPS_WEBHOOK_TOKEN / AIOPS_MODEL_KEY 配置，绝不填写在 URL。</p></article></section>
<section v-if="tab==='审计'"><article class="panel"><h2>操作审计 <small>最近 200 条 · 不记录原始日志与凭据</small></h2><table><thead><tr><th>时间</th><th>操作</th><th>对象 ID</th></tr></thead><tbody><tr v-for="a in audit" :key="a.id"><td>{{new Date(a.at).toLocaleString()}}</td><td>{{a.action}}</td><td>{{a.entity}}</td></tr></tbody></table><div v-if="!audit.length" class="empty">暂无操作记录</div></article></section>
<footer>观云 AIOPS · 0.1 MVP <span>诊断建议不等于已确认根因 · 生产认证 / RBAC 尚未实现</span></footer>
</main></div>
</template>
